export type Quote = {
  id: string;
  author: string;
  role: string;
  company: string;
  quote: string;
  rating: number;
  handle: string;
  time: string;
  mark: string;
};

export type QuoteLabels = {
  /** template of the rating's accessible name, e.g. `｛0｝ out of 5` */
  rating: string;
  /** template of the line under the author, e.g. `｛0｝, ｛1｝` (role, company) */
  byLine: string;
  /** template of the line under a social author, e.g. `｛0｝ / ｛1｝` (handle, time) */
  handleLine: string;
};

export type QuoteItem = {
  /** card: boxed; plain: a bare figure; social: a post of a social wall */
  kind?: "card" | "plain" | "social";
  /** a round picture of the author */
  avatar?: "none" | "image";
  /** the stars (not on social posts) */
  rating?: "show" | "hide";
  /** a company glyph above the quote */
  mark?: "none" | "icon";
};
